    Bug 2075517 - Fix IMAP [ALERT] de-duplication to compare the alert text. r=babolivier

    The check meant to avoid showing the same alert repeatedly compared the
    "ALERT]" token with the last alert's text, so it never matched. Compare
    the alert text instead, and record [UNAVAILABLE] even when its alert
    isn't shown again.

    Differential Revision: https://phabricator.services.mozilla.com/D329381

diff --git a/mailnews/imap/src/nsImapServerResponseParser.cpp b/mailnews/imap/src/nsImapServerResponseParser.cpp
index efdc17d49c5..712feaa212c 100644
--- a/mailnews/imap/src/nsImapServerResponseParser.cpp
+++ b/mailnews/imap/src/nsImapServerResponseParser.cpp
@@ -1614,13 +1614,14 @@ void nsImapServerResponseParser::resp_text_code() {
       // Treat ALERT and UNAVAILABLE response codes similarly. Show response
       // code string in pop-up. See RFC 5530 "IMAP Response Codes".
       char* alertMsg = fCurrentTokenPlaceHolder;  // advance past ALERT/UNAVAIL
-      if (alertMsg && *alertMsg &&
-          (!fLastAlert || PL_strcmp(fNextToken, fLastAlert))) {
-        fServerConnection.AlertUserEvent(alertMsg);
-        PR_Free(fLastAlert);
-        fLastAlert = PL_strdup(alertMsg);
+      if (alertMsg && *alertMsg) {
         // If UNAVAILABLE, flag this to prevent a possible password prompt
         fServerUnavailable = (NS_ToUpper(fNextToken[0]) == 'U');
+        if (!fLastAlert || PL_strcmp(alertMsg, fLastAlert)) {
+          fServerConnection.AlertUserEvent(alertMsg);
+          PR_Free(fLastAlert);
+          fLastAlert = PL_strdup(alertMsg);
+        }
       }
       AdvanceToNextToken();
     } else if (!PL_strcasecmp(fNextToken, "PARSE]")) {
diff --git a/mailnews/imap/test/unit/test_imapAlertRepeated.js b/mailnews/imap/test/unit/test_imapAlertRepeated.js
